function RequestOperations() { return <RoleWorkspace eyebrow="Operations" title="Request operations" description="Live intake volume, routing, and service-level performance." metrics={[["Open requests","214"],["Unassigned","7"],["Within target","91%"]]} rows={[["Commercial contracting","86 open","Median 3.8 days"],["Privacy review","42 open","Median 5.1 days"],["Specialist escalation","18 open","Median 2.4 days"]]} />; }
function QualityReview() { return <RoleWorkspace eyebrow="Administration" title="Quality review" description="Answers and workflows that need operational review." metrics={[["Review sample","36"],["Passed","33"],["Follow-up needed","3"]]} rows={[["Low-confidence answer","Ask CPS · Data residency","Assigned to Quality team"],["Citation mismatch","AI liability guidance","Needs source update"],["User feedback","Matter CPS-2027-01431","Review requested"]]} />; }
function AdminSettings({ state, update }: { state: DemoState; update: (p: Partial<DemoState>) => void }) { const enabled = state.routingRuleEnabled !== false; const [editor, setEditor] = useState<string | null>(null); return <div className="page role-workspace"><header><span className="eyebrow">Administration</span><h1>CPS settings</h1><p>Manage operational rules with confirmation and auditability.</p></header><div className="role-metrics"><Metric label="Connected systems" value="5" /><Metric label="Active workflows" value={enabled ? "12" : "11"} /><Metric label="Admin alerts" value="1" /></div><section><div className="section-heading"><div><h2>Routing and synchronization</h2><p>Changes affect new requests only.</p></div></div><div className="admin-list"><div><span><strong>Route strategic AI matters to specialist queue</strong><small>EMEA · Enterprise · Azure AI · $10M+</small></span><Status tone={enabled ? "success" : "neutral"}>{enabled ? "Enabled" : "Disabled"}</Status><Button onClick={() => update({ adminConfirmOpen: true })}>{enabled ? "Disable" : "Enable"}</Button></div><div><span><strong>Forecast field mapping</strong><small>Category, close date, probability, value, change reason</small></span><Status tone="success">Synced</Status><Button onClick={() => setEditor("forecast")}>Review mapping</Button></div><div><span><strong>Training assignment rule</strong><small>Assign AI-risk practice when liability signal is detected</small></span><Status tone="success">Active</Status><Button onClick={() => setEditor("training")}>Review rule</Button></div><div><span><strong>Microsoft 365 connections</strong><small>Teams, Word, SharePoint, Outlook, Dynamics 365</small></span><Status tone="success">Connected</Status><Button onClick={() => setEditor("connections")}>View health</Button></div></div></section><Accordion collapsible><AccordionItem value="audit"><AccordionHeader>Administration audit history</AccordionHeader><AccordionPanel><div className="audit-list"><span><strong>{enabled ? "Strategic AI routing enabled" : "Strategic AI routing disabled"}</strong><small>Today · CPS Administrator</small></span><span><strong>Forecast mapping verified</strong><small>Aug 20 · Revenue Operations</small></span></div></AccordionPanel></AccordionItem></Accordion><Dialog open={Boolean(state.adminConfirmOpen)} onOpenChange={(_, d) => update({ adminConfirmOpen: d.open })}><DialogSurface><DialogBody><DialogTitle>{enabled ? "Disable routing rule?" : "Enable routing rule?"}</DialogTitle><DialogContent><p>This changes how new EMEA strategic AI matters are assigned. Existing matters will not move.</p></DialogContent><DialogActions><Button onClick={() => update({ adminConfirmOpen: false })}>Cancel</Button><Button appearance="primary" onClick={() => update({ adminConfirmOpen: false, routingRuleEnabled: !enabled })}>Confirm change</Button></DialogActions></DialogBody></DialogSurface></Dialog><AdminEditorDialog editor={editor} onClose={() => setEditor(null)} /></div>; }
function AdminEditorDialog({ editor, onClose }: { editor: string | null; onClose: () => void }) { const config = editor === "forecast" ? { title:"Forecast field mapping", description:"Map CPS recommendations to the connected CRM opportunity.", fields:[["Forecast category","forecastcategory"],["Estimated close","estimatedclosedate"],["Probability","closeprobability"],["Change reason","cps_forecastreason"]] } : editor === "training" ? { title:"Training assignment rule", description:"Assign contextual learning when the selected deal signals are detected.", fields:[["Trigger","AI liability outside standard"],["Audience","Opportunity owner and manager"],["Module","Positioning AI risk without overpromising"],["Due","Before next customer meeting"]] } : { title:"Microsoft 365 connection health", description:"Connection checks completed today at 10:32 AM.", fields:[["Teams","Connected · notifications healthy"],["Word","Connected · document access healthy"],["SharePoint","Connected · 4 sources indexed"],["Dynamics 365","Connected · forecast sync healthy"]] }; return <Dialog open={Boolean(editor)} onOpenChange={(_, d) => !d.open && onClose()}><DialogSurface><DialogBody><DialogTitle>{config.title}</DialogTitle><DialogContent><p>{config.description}</p><div className="config-fields">{config.fields.map(([label,value]) => <label key={label}><span>{label}</span><Input value={value} readOnly={editor === "connections"} /></label>)}</div></DialogContent><DialogActions><Button onClick={onClose}>Cancel</Button>{editor !== "connections" && <Button appearance="primary" onClick={onClose}>Save configuration</Button>}</DialogActions></DialogBody></DialogSurface></Dialog>; }
function RoleWorkspace({ eyebrow, title, description, metrics, rows }: { eyebrow: string; title: string; description: string; metrics: string[][]; rows: string[][] }) { const [selected, setSelected] = useState<string | null>(null); return <div className="page role-workspace"><header><span className="eyebrow">{eyebrow}</span><h1>{title}</h1><p>{description}</p></header><div className="role-metrics">{metrics.map(([label,value]) => <Metric key={label} label={label} value={value} />)}</div><section><div className="section-heading"><h2>Current view</h2><Button>Filter</Button></div><div className="workspace-list">{rows.map(([name,detail,status]) => <button key={name} onClick={() => setSelected(selected === name ? null : name)}><span><strong>{name}</strong><small>{detail}</small></span><span>{status}</span><ChevronRight20Regular /></button>)}</div>{selected && <div className="workspace-detail"><span className="eyebrow">Selected item</span><h3>{selected}</h3><p>This drill-down is scoped to the selected record and preserves the current persona and filters.</p><div className="issue-facts"><span><strong>Owner</strong>CPS Operations</span><span><strong>Last updated</strong>Today · 10:32 AM</span></div><Button>Open full record</Button></div>}</section></div>; }
function NewRequest({ onCancel, onContinue }: { onCancel: () => void; onContinue: () => void }) { const [text, setText] = useState(""); return <div className="page intake-page"><header><span className="eyebrow">New request</span><h1>What are you working on?</h1><p>Describe the customer request or decision CPS can help with.</p></header><section className="intake-form"><label htmlFor="request">Your request</label><Textarea id="request" value={text} onChange={(_, d) => setText(d.value)} resize="vertical" /><div className="upload-zone"><Attach20Regular /><div><strong>Add supporting material</strong><span>Agreement, customer document, or email</span></div><Button>Add file</Button></div><div className="suggested-deal"><div><small>Matched from Dynamics 365</small><strong>{matter.title}</strong><span>{matter.compactValue} · Germany · Azure AI</span></div><Status tone="success">Matched</Status></div><div className="intake-actions"><Button onClick={onCancel}>Cancel</Button><Button appearance="primary" disabled={!text.trim()} onClick={onContinue}>Start request</Button></div></section></div>; }
function AppGallery({ onOpen, onClose }: { onOpen: () => void; onClose: () => void }) { const apps = [["O", "Outlook"], ["T", "Teams"], ["W", "Word"], ["E", "Excel"], ["S", "SharePoint"], ["P", "Planner"]]; return <div className="m365-gallery"><header><span /><strong>Microsoft 365</strong><Input placeholder="Search apps" aria-label="Search apps" /><Avatar name="Maya Chen" size={32} /></header><main><div className="gallery-heading"><div><h1>Apps</h1><p>Work, create, and collaborate from one place.</p></div><Button onClick={onClose}>Close</Button></div><div className="app-grid">{apps.map(([letter, name]) => <div className="app-tile" key={name}><span className={`gallery-icon ${name.toLowerCase()}`}>{letter}</span><strong>{name}</strong></div>)}<button className="cps-app" onClick={onOpen}><DealRoomMark /><span><strong>CPS Deal Room</strong><small>Bring business and Legal together to get deals done.</small></span></button></div></main></div>; }
function DecisionDialog({ selected, onClose, onComplete }: { selected: number | null; onClose: () => void; onComplete: () => void }) { const d = selected === null ? null : matter.decisions[selected]; return <Dialog open={Boolean(d)} onOpenChange={(_, x) => !x.open && onClose()}><DialogSurface><DialogBody><DialogTitle>{d?.title}</DialogTitle><DialogContent>{d && <><span className="eyebrow">Decision needed</span><h3>{d.recommendation}</h3><p>{d.rationale}</p><Accordion collapsible><AccordionItem value="trace"><AccordionHeader>Guidance and comparable matters</AccordionHeader><AccordionPanel>Commercial contracting playbook v4.3 and three comparable enterprise matters support this recommendation. Deployment facts may still require specialist input.</AccordionPanel></AccordionItem></Accordion></>}</DialogContent><DialogActions><Button onClick={onClose}>Cancel</Button><Button appearance="primary" onClick={onComplete}>{selected === 0 ? "Use fallback" : "Request Privacy input"}</Button></DialogActions></DialogBody></DialogSurface></Dialog>; }
